import{_ as a,o as e,c as i,a5 as s}from"./chunks/framework.CXroN2RO.js";const u=JSON.parse('{"title":"コンパイラ最適化・未定義動作の影響・Debug/Release・ゼロコスト抽象化","description":"","frontmatter":{"title":"コンパイラ最適化・未定義動作の影響・Debug/Release・ゼロコスト抽象化","study":{"source":"C++ Wiki","status":"published","summary":"コンパイラは「観測可能な動作(出力・volatileアクセス等)が同じなら、コードを何をしてもよい」(as-ifルール)という原則で変形します。主な最適化: コンパイラは「UBは起きない」という前提で変形します。UBのページの続きを、最適化の視点から:","section":"reference","format":"article","domain":"compilers"}},"headers":[],"relativePath":"runtime/cpp-internals/optimization-and-ub.md","filePath":"runtime/cpp-internals/optimization-and-ub.md"}'),n={name:"runtime/cpp-internals/optimization-and-ub.md"};function d(l,t,r,o,h,p){return e(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="コンパイラ最適化・未定義動作の影響・debug-release・ゼロコスト抽象化" tabindex="-1">コンパイラ最適化・未定義動作の影響・Debug/Release・ゼロコスト抽象化 <a class="header-anchor" href="#コンパイラ最適化・未定義動作の影響・debug-release・ゼロコスト抽象化" aria-label="Permalink to &quot;コンパイラ最適化・未定義動作の影響・Debug/Release・ゼロコスト抽象化&quot;">​</a></h1><h2 id="コンパイラ最適化-—-何をしているのか" tabindex="-1">コンパイラ最適化 — 何をしているのか <a class="header-anchor" href="#コンパイラ最適化-—-何をしているのか" aria-label="Permalink to &quot;コンパイラ最適化 — 何をしているのか&quot;">​</a></h2><p>コンパイラは「<strong>観測可能な動作</strong>(出力・volatileアクセス等)が同じなら、コードを何をしてもよい」(as-ifルール)という原則で変形します。主な最適化:</p><table tabindex="0"><thead><tr><th>最適化</th><th>内容</th><th>例</th></tr></thead><tbody><tr><td>定数畳み込み・伝播</td><td>コンパイル時に計算</td><td><code>60*60</code> → <code>3600</code>、その値を使う先も連鎖的に</td></tr><tr><td>インライン展開</td><td>呼び出しを本体で置換</td><td>→ <a href="/study/runtime/cpp-internals/template-instantiation-and-inline.html">inlineの実際</a></td></tr><tr><td>デッドコード除去</td><td>結果が使われないコードの削除</td><td>「計測用ループが丸ごと消えて0ms」の正体</td></tr><tr><td>ループ変形</td><td>不変式の巻き上げ、展開、ベクトル化</td><td><code>for</code>内の<code>v.size()</code>呼び出しを外へ</td></tr><tr><td>レジスタ割付</td><td>変数をメモリに置かない</td><td>→ <a href="/study/runtime/cpp-internals/function-calls-and-cpu.html">レジスタ</a></td></tr><tr><td>命令並べ替え</td><td>依存のない命令の順序変更</td><td>パイプライン効率化(→ マルチスレッドで<a href="/study/runtime/memory/concurrency-bugs.html">メモリモデル</a>問題の遠因)</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>最適化レベル: -O0(なし・デバッグ用) / -O1 / -O2(標準) / -O3(積極) / -Os(サイズ優先)</span></span>
<span class="line"><span>MSVC: /Od(なし) / /O2(速度)。LTO(-flto, /GL)でリンク時に翻訳単位を越えて最適化</span></span></code></pre></div><h2 id="未定義動作が最適化に与える影響-このページの核心" tabindex="-1">未定義動作が最適化に与える影響(このページの核心) <a class="header-anchor" href="#未定義動作が最適化に与える影響-このページの核心" aria-label="Permalink to &quot;未定義動作が最適化に与える影響(このページの核心)&quot;">​</a></h2><p>コンパイラは「<strong>UBは起きない</strong>」という前提で変形します。<a href="/study/languages/cpp/undefined-behavior.html">UBのページ</a>の続きを、最適化の視点から:</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 例1: 符号付きオーバーフローはUB → 「起きない」前提でループを変形</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> n; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">++</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">i) { ... }</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// もし n == INT_MAX なら i&lt;=n は常に真(無限ループ)だが、</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// コンパイラは「オーバーフローは起きない=ループは有限」とみなして</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 回数を事前計算する等の変形をする。実行時の挙動は「壊れ方すら不定」になる</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 例2: nullチェックの削除(→ UBページの例)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 例3: 未初期化変数 → 「どんな値と仮定してもよい」→ 分岐ごと消える</span></span></code></pre></div><p><strong>重要な帰結</strong>: 「-O0では動くが-O2で壊れる」の大半は<strong>コンパイラのバグではなく、自分のコードのUBが最適化で顕在化</strong>したもの。逆に言うと、UBフリーなコードは最適化レベルを上げても意味が変わりません——これが「UBを書かない」ことの実利です。</p><h2 id="デバッグビルドとリリースビルドの違い" tabindex="-1">デバッグビルドとリリースビルドの違い <a class="header-anchor" href="#デバッグビルドとリリースビルドの違い" aria-label="Permalink to &quot;デバッグビルドとリリースビルドの違い&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Debug (-O0, /Od)</th><th>Release (-O2, /O2)</th></tr></thead><tbody><tr><td>最適化</td><td>なし(コードは書いた通り)</td><td>上記すべて</td></tr><tr><td>変数</td><td>全部メモリにあり、デバッガで見える</td><td>レジスタ化・消滅で「見えない」「値が飛ぶ」</td></tr><tr><td>ステップ実行</td><td>行と命令が対応</td><td>インライン化・並べ替えで行が飛ぶ</td></tr><tr><td>assert / チェック</td><td>有効(NDEBUG未定義)</td><td>assertは無効化が通例</td></tr><tr><td>STL</td><td>チェック付き(MSVCのデバッグイテレータ等)で<strong>桁違いに遅いことがある</strong></td><td>高速</td></tr><tr><td>速度</td><td>ゲームによっては遊べない遅さ</td><td>本番速度</td></tr></tbody></table><ul><li>ゲーム開発では中間の<strong>Development/Profile構成</strong>(最適化あり+一部チェック・計測機能)を持つのが普通(→ <a href="/study/tools/build/build-configurations.html">ビルド構成</a>)</li><li><strong>「Debugでだけ再現するバグ」「Releaseでだけ壊れるバグ」の両方が正常にあり得る</strong>(初期化パターン・タイミング・レイアウトが変わるため)。Releaseビルドのテストを後回しにしない</li></ul><h2 id="ゼロコスト抽象化" tabindex="-1">ゼロコスト抽象化 <a class="header-anchor" href="#ゼロコスト抽象化" aria-label="Permalink to &quot;ゼロコスト抽象化&quot;">​</a></h2><p>C++の設計哲学:「<strong>使わない機能の代金は払わない。使う抽象は手書きの低レベルコードと同等になるべき</strong>」。</p><table tabindex="0"><thead><tr><th>抽象</th><th>実行時コスト</th></tr></thead><tbody><tr><td>クラス(非virtual)・名前空間・const・テンプレート</td><td>ゼロ(コンパイル時に消える)</td></tr><tr><td><code>unique_ptr</code> / <code>vector&lt;T&gt;</code>の<code>[]</code> / range-for / ラムダのインライン適用</td><td>手書き相当(最適化前提)</td></tr><tr><td>仮想関数 / RTTI / 例外(投げた時) / <code>std::function</code> / <code>shared_ptr</code></td><td><strong>有料</strong>(選んで使う)</td></tr></tbody></table><ul><li>「ゼロコスト」は<strong>最適化ビルドで</strong>の話。-O0ではunique_ptrの間接層もそのまま残る(Debugビルドが遅い一因)</li><li>C#との対照: 抽象の多く(クラス=ヒープ+GC、interface呼び出し、デリゲート)が常に有料で、選べない。C++は<strong>コスト表を見て選ぶ言語</strong>——本Wikiの各ページで「コスト」を毎回書いてきたのはこのため</li></ul><h2 id="unity開発者が誤解しやすい点" tabindex="-1">Unity開発者が誤解しやすい点 <a class="header-anchor" href="#unity開発者が誤解しやすい点" aria-label="Permalink to &quot;Unity開発者が誤解しやすい点&quot;">​</a></h2><ol><li>「デバッガで変数が見えない=壊れている」— Releaseでは正常(最適化で消えただけ)。調査はDebug/Developmentビルドで</li><li>「エディタで動けばOK」— UnityエディタはMono/JITでDebug相当。IL2CPPリリースビルドは最適化されたC++の世界で、このページの差異がそのまま現れる</li><li>ベンチマークの罠: 結果を使わない計測コードはデッドコード除去で消える(「0msになった!」)。結果をvolatileや出力で「観測」させる</li></ol><h2 id="ゲーム開発での使用例" tabindex="-1">ゲーム開発での使用例 <a class="header-anchor" href="#ゲーム開発での使用例" aria-label="Permalink to &quot;ゲーム開発での使用例&quot;">​</a></h2><ul><li>出荷ビルドだけのバグ調査: UB検出(サニタイザ)→最適化差の切り分け、という手順を知っている人が強い</li><li>フレーム最適化: プロファイル→ホットパスのデータ設計(<a href="/study/runtime/cpp-internals/cache-branch-simd.html">前ページ</a>)→それでも足りなければintrinsics</li><li>assert・ログを構成別に制御し、Shippingではゼロコストにする設計</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>as-ifルールとは何ですか。「観測可能な動作」に含まれないものの例は?</li><li>「-O2で壊れた」ときにまず疑うべきものは?</li><li>「ゼロコスト抽象化」の正確な意味と、その前提条件は?</li></ol><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><p>godbolt.orgで、(a) 結果を使わないループが-O2で消えること、(b) <code>std::unique_ptr</code> 経由のアクセスが-O2で生ポインタと同じコードになること、を確認してください。</p><hr><p>関連項目：<a href="/study/runtime/cpp-internals/cache-branch-simd.html">キャッシュ・分岐予測・SIMD</a> / <a href="/study/runtime/cpp-internals/">学習ガイド</a> / <a href="/study/runtime/cpp-internals/exercises.html">演習</a></p>`,26)])])}const g=a(n,[["render",d]]);export{u as __pageData,g as default};
